    app.run(until="1 h")
    readings = app.env.stats.readings()
    for name in ("pick_order", "backorder", "pack_order", "ship_order"):
        print(f"{name:&lt;10}: {readings[f'Shop.stats.tasks.{name}.finished']} finished")
