    return env


def mean_waits(
    queue: str, orders_rate: float = 0.45, express_rate: float = 0.15
) -&gt; dict:
    """Runs one hour and returns the mean wait of each task."""
    readings = run(
        queue, orders_rate=orders_rate, express_rate=express_rate
